  3	/** Sends e-mails to guests. Every e-mail sent is kept in the list of sent messages. */
  4	public final class EmailSender {
  5	
  6	    private final SentMessages sentMessages;
  7	
  8	    public EmailSender(SentMessages sentMessages) {
  9	        this.sentMessages = sentMessages;
 10	    }
 11	
 12	    public Message send(String to, String subject, String body) {
 13	        return sentMessages.add("EMAIL", to, subject, body);
 14	    }
 15	}
 16	package hotel.messages;
 17	
 18	import java.sql.Connection;
 19	import java.sql.PreparedStatement;
 20	import java.sql.ResultSet;
 21	import java.sql.SQLException;
 22	import java.util.ArrayList;
 23	import java.util.List;
 24	import javax.sql.DataSource;
 25	
 26	/** Every message the inn sent, so the front desk can check what each guest received. */
 27	public final class SentMessages {
 28	
 29	    private final DataSource dataSource;
 30	
 31	    public SentMessages(DataSource dataSource) {
 32	        this.dataSource = dataSource;
 33	    }
 34	
 35	    Message add(String channel, String to, String subject, String body) {
 36	        try (Connection connection = dataSource.getConnection();
 37	                PreparedStatement insert = connection.prepareStatement(
 38	                        "INSERT INTO messages (channel, recipient, subject, body) VALUES (?, ?, ?, ?) RETURNING id")) {
 39	            insert.setString(1, channel);
 40	            insert.setString(2, to);
 41	            insert.setString(3, subject);
 42	            insert.setString(4, body);
 43	            try (ResultSet generated = insert.executeQuery()) {
 44	                generated.next();
 45	                return new Message(generated.getLong("id"), channel, to, subject, body);
 46	            }
 47	        } catch (SQLException failure) {
 48	            throw new IllegalStateException("could not keep the message to " + to, failure);
 49	        }
 50	    }
 51	
 52	    public List<Message> all() {
 53	        try (Connection connection = dataSource.getConnection();
 54	                PreparedStatement select = connection.prepareStatement(
 55	                        "SELECT id, channel, recipient, subject, body FROM messages ORDER BY id");
 56	                ResultSet rows = select.executeQuery()) {
 57	            List<Message> messages = new ArrayList<>();
 58	            while (rows.next()) {
 59	                messages.add(new Message(
 60	                        rows.getLong("id"),
 61	                        rows.getString("channel"),
 62	                        rows.getString("recipient"),
 63	                        rows.getString("subject"),
 64	                        rows.getString("body")));
 65	            }
 66	            return messages;
 67	        } catch (SQLException failure) {
 68	            throw new IllegalStateException("could not read the sent messages", failure);
 69	        }
 70	    }
 71	}

