281	import java.sql.Connection;
282	import java.sql.PreparedStatement;
283	import java.sql.ResultSet;
284	import java.sql.SQLException;
285	import java.util.ArrayList;
286	import java.util.List;
287	import java.util.Optional;
288	import javax.sql.DataSource;
289	
290	/** The inn's rooms. They rarely change, so they come with the database schema. */
291	public final class Rooms {
292	
293	    private final DataSource dataSource;
294	
295	    public Rooms(DataSource dataSource) {
296	        this.dataSource = dataSource;
297	    }
298	
299	    public List<Room> all() {
300	        try (Connection connection = dataSource.getConnection();
301	                PreparedStatement select = connection.prepareStatement(
302	                        "SELECT number, type, capacity, nightly_rate FROM rooms ORDER BY number");
303	                ResultSet rows = select.executeQuery()) {
304	            List<Room> rooms = new ArrayList<>();
305	            while (rows.next()) {
306	                rooms.add(read(rows));
307	            }
308	            return rooms;
309	        } catch (SQLException failure) {
310	            throw new IllegalStateException("could not read the rooms", failure);
311	        }
312	    }
313	
314	    public Optional<Room> find(int roomNumber) {
315	        try (Connection connection = dataSource.getConnection();
316	                PreparedStatement select = connection.prepareStatement(
317	                        "SELECT number, type, capacity, nightly_rate FROM rooms WHERE number = ?")) {
318	            select.setInt(1, roomNumber);
319	            try (ResultSet rows = select.executeQuery()) {
320	                return rows.next() ? Optional.of(read(rows)) : Optional.empty();
321	            }
322	        } catch (SQLException failure) {
323	            throw new IllegalStateException("could not read room " + roomNumber, failure);
324	        }
325	    }
326	
327	    private static Room read(ResultSet row) throws SQLException {
328	        return new Room(
329	                row.getInt("number"),
330	                RoomType.valueOf(row.getString("type")),
331	                row.getInt("capacity"),
332	                row.getBigDecimal("nightly_rate"));
333	    }
334	}

